  },
  {
    name: "Quillbase",
    render: () => (
      <svg viewBox="0 0 28 28" className="size-6" fill="none" aria-hidden="true">
        <path
          d="M14 3 25 9v10l-11 6L3 19V9z"
          stroke="currentColor"
          strokeWidth="2.5"
          strokeLinejoin="round"
        />
        <path d="M14 11v6" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" />
